import{_ as t,o as n,c as r,a2 as i}from"./chunks/framework.vLhlLNVn.js";const g=JSON.parse('{"title":"Falsche Werte und bekannte Fehler älterer Versionen","description":"","frontmatter":{"order":2,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/de/04.fehlerbehebung/02.falsche-werte-und-bekannte-fehler.md"},"headers":[],"relativePath":"de/adapter/sourceanalytix/fehlerbehebung/falsche-werte-und-bekannte-fehler.md","filePath":"de/adapter/sourceanalytix/fehlerbehebung/falsche-werte-und-bekannte-fehler.md","lastUpdated":null}'),a={name:"de/adapter/sourceanalytix/fehlerbehebung/falsche-werte-und-bekannte-fehler.md"};function l(s,e,d,o,h,u){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="falsche-werte-und-bekannte-fehler-alterer-versionen" tabindex="-1">Falsche Werte und bekannte Fehler älterer Versionen <a class="header-anchor" href="#falsche-werte-und-bekannte-fehler-alterer-versionen" aria-label="Permalink to &quot;Falsche Werte und bekannte Fehler älterer Versionen&quot;">​</a></h1><p><a id="values-costs-far-too-high"></a></p><h2 id="werte-oder-kosten-viel-zu-hoch-oder-negativ-–-stimmt-die-einheit" tabindex="-1">Werte oder Kosten viel zu hoch oder negativ – stimmt die Einheit? <a class="header-anchor" href="#werte-oder-kosten-viel-zu-hoch-oder-negativ-–-stimmt-die-einheit" aria-label="Permalink to &quot;Werte oder Kosten viel zu hoch oder negativ – stimmt die Einheit?&quot;">​</a></h2><p>Meist passt eine Einheit nicht: an der Quelle, beim Preis oder bei einem Startwert. Prüfe sie in der Detailansicht der Quelle und korrigiere danach die Werte.</p><table tabindex="0"><thead><tr><th>Falsch</th><th>Folge</th><th>Richtig</th></tr></thead><tbody><tr><td>Einheit <code>kWh</code>, Gerät liefert <code>Wh</code></td><td>alles 1.000-mal zu groß</td><td>Einheit, die das Gerät liefert</td></tr><tr><td>Zählerstand als <code>kW</code> beschriftet</td><td>Werte wachsen viel zu schnell</td><td>Zählerstand in <code>kWh</code>, Leistung in <code>W</code></td></tr><tr><td>Preis in Cent, <code>28.5</code> statt <code>0.285</code></td><td>Kosten 100-mal zu hoch</td><td>Preis in Euro je Einheit</td></tr><tr><td>Startwert in <code>Wh</code>, Preis in <code>kWh</code></td><td>Verbrauch stark negativ</td><td>Startwert in kWh</td></tr></tbody></table><p>Oben in der Detailansicht steht die „Art“, etwa „Zählerstand · kWh“, darunter der „Gesamtstand“. Vergleiche ihn mit deinem Zähler und prüfe dann „Einheit“ und „Preisdefinition“ unter „Einstellungen“. Unpassende Startwerte meldet der Tab „Probleme“ als „Startwert passt nicht“.</p><p>Gespeicherte Werte ändern sich mit der Einheit nicht. Bring danach den Gesamtstand mit „Zählerstand angleichen“ in Ordnung und rechne die Kosten mit „Kosten ab Datum neu rechnen“ neu, siehe <a href="./../anleitungen/zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Falsche Werte korrigieren</a>.</p><p><strong>Siehe auch:</strong> <a href="./../anleitungen/quellen-und-einheiten#unit-datapoint-kwh-wh-m3">Welche Einheit am Datenpunkt?</a> · <a href="./../anleitungen/zaehlerstaende-korrigieren#values-negative-after-entering-start">Negative Werte nach Startwerten</a></p><p><a id="after-update-restore-values-0"></a></p><h2 id="nach-update-oder-restore-sind-werte-0-oder-sourceanalytix-fehlt" tabindex="-1">Nach Update oder Restore sind Werte 0 oder SourceAnalytix fehlt <a class="header-anchor" href="#nach-update-oder-restore-sind-werte-0-oder-sourceanalytix-fehlt" aria-label="Permalink to &quot;Nach Update oder Restore sind Werte 0 oder SourceAnalytix fehlt&quot;">​</a></h2><p>Nach einem Restore fehlt oft der Adapter selbst, denn ein Backup sichert Daten, keinen Programmcode. Installiere SourceAnalytix aus „latest“ neu; die gesicherte Instanz läuft dann weiter. Ein Update ändert deine Werte nicht.</p><p>Nach einem Restore können Gesamtstand und Einstellungen aus verschiedenen Zeitpunkten stammen:</p><ol><li>Öffne die Quelle und vergleiche den „Gesamtstand“ mit deinem Zähler.</li><li>Stimmt er nicht, nimm „Zählerstand angleichen“.</li><li>Hole im Tab „Probleme“ einen „Periodenwechsel verpasst“ mit „Nachholen“ nach.</li></ol><p><strong>Siehe auch:</strong> <a href="./../anleitungen/betrieb-und-wartung#data-back-up-move-new">Wo liegen die Daten?</a></p><p><a id="costs-stay-0-not-calculated"></a></p><h2 id="kosten-bleiben-0-oder-werden-nicht-berechnet" tabindex="-1">Kosten bleiben 0 oder werden nicht berechnet <a class="header-anchor" href="#kosten-bleiben-0-oder-werden-nicht-berechnet" aria-label="Permalink to &quot;Kosten bleiben 0 oder werden nicht berechnet&quot;">​</a></h2><p>Kosten entstehen nur mit dem Haken „Kosten“ bei der Quelle und einem gültigen „Preis pro Einheit“. Bei der Kostenart „Erträge“ stehen sie unter <code>earnings</code>, nicht unter <code>costs</code>.</p><ol><li><strong>„Kosten“ an?</strong> Prüfe es in der Detailansicht unter „Einstellungen“.</li><li><strong>Preisdefinition gewählt?</strong> Sonst meldet es der Tab „Probleme“.</li><li><strong>Preis eine Zahl?</strong> Sonst rechnet SourceAnalytix mit 0 und meldet <code>Price definition &lt;Name&gt; has no valid unit price …</code> im Log.</li><li><strong>Preis aus einem Datenpunkt?</strong> Liefert er nichts Gültiges, gilt der eingetragene „Preis pro Einheit“; ist der leer, bleiben die Kosten 0.</li></ol><p>Danach rechnet „Kosten ab Datum neu rechnen“ die Kosten mit dem Preisverlauf nach.</p><p><strong>Siehe auch:</strong> <a href="./../anleitungen/preise-und-kosten#assign-prices-create-custom-tariffs">Preise zuordnen</a> · <a href="./../anleitungen/quellen-und-einheiten#track-pv-yield-feed-earnings">PV-Ertrag und Einspeisung</a></p><p><a id="huge-consumption-after-power-outage"></a></p><h2 id="nach-stromausfall-riesiger-verbrauch-bei-leistungsquellen" tabindex="-1">Nach Stromausfall riesiger Verbrauch bei Leistungsquellen <a class="header-anchor" href="#nach-stromausfall-riesiger-verbrauch-bei-leistungsquellen" aria-label="Permalink to &quot;Nach Stromausfall riesiger Verbrauch bei Leistungsquellen&quot;">​</a></h2><p>Bei Leistung gilt der letzte Wert, bis ein neuer kommt. Fällt das Gerät aus, ohne 0 zu melden, wird die letzte Leistung über die ganze Pause hochgerechnet. Das verhindert „Maximale Lücke zwischen Leistungswerten (Minuten)“.</p><ol><li>Öffne die Leistungsquelle.</li><li>Trage unter „Einstellungen“ bei „Maximale Lücke zwischen Leistungswerten (Minuten)“ einen Wert deutlich über dem längsten normalen Abstand zweier Werte ein.</li><li>Klicke auf „⚡ Übernehmen“. Längere Lücken zählen dann als 0.</li></ol><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Lass das Feld leer, wenn dein Gerät nur bei Änderungen sendet. Sonst fehlt der Verbrauch langer gleichbleibender Abschnitte.</p></div><p>Kommt drei Stunden lang kein Wert, meldet der Tab „Probleme“ „Leistungsquelle meldet seit langem keinen Wert“. Schon gebuchte Werte reparierst du wie unter <a href="./../anleitungen/zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Falsche Werte korrigieren</a>.</p><p><a id="so-many-decimals"></a></p><h2 id="warum-so-viele-nachkommastellen" tabindex="-1">Warum so viele Nachkommastellen? <a class="header-anchor" href="#warum-so-viele-nachkommastellen" aria-label="Permalink to &quot;Warum so viele Nachkommastellen?&quot;">​</a></h2><p>Wahrscheinlich steht die Rundung der Quelle auf <code>-1</code>, also ungerundet. Standard sind 3 Stellen für Verbrauch und 2 für Kosten. Du änderst sie in der Detailansicht der Quelle unter „Für Experten“.</p><p>Die Werte unter „Haupteinstellungen“ › „Rundung“ gelten nur für neue Quellen. Wie viele Stellen, Nullen oder Tausenderpunkte du siehst, legt außerdem deine Anzeige fest, etwa VIS.</p><p><a id="known-bugs-older-versions-please"></a></p><h2 id="bekannte-fehler-alterer-versionen-–-bitte-aktualisieren" tabindex="-1">Bekannte Fehler älterer Versionen – bitte aktualisieren <a class="header-anchor" href="#bekannte-fehler-alterer-versionen-–-bitte-aktualisieren" aria-label="Permalink to &quot;Bekannte Fehler älterer Versionen – bitte aktualisieren&quot;">​</a></h2><p>Aktualisiere auf die aktuelle Version. Diese Doku beschreibt nur sie; welcher Fehler in welcher Version behoben wurde, steht im <a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/blob/main/README.md#changelog" target="_blank" rel="noreferrer">Changelog</a>. Viele Meldungen aus dem Forum, etwa doppelte Werte nach einem Reset oder fehlende Tageswechsel, betreffen alte Versionen.</p><p>Danach zeigt der Tab „Probleme“ die meisten Ursachen falscher Werte direkt mit einem Knopf zur Lösung.</p><p><strong>Siehe auch:</strong> <a href="./../anleitungen/betrieb-und-wartung#update-sourceanalytix-downgrade">Wie aktualisiere ich SourceAnalytix?</a></p>',35)])])}const m=t(a,[["render",l]]);export{g as __pageData,m as default};
